import { useEffect, useState, useRef } from "react";
import Loader from "react-loaders";
import AnimatedLetters from "../AnimatedLetters";
import useInView from "../../hooks/useInView";
import emailjs from "@emailjs/browser";
import "./index.scss";

const Contact = () => {
  const [letterClass, setLetterClass] = useState("text-animate");
  const [ref, inView] = useInView();
  const formRef = useRef(null);
  const [status, setStatus] = useState("");

  useEffect(() => {
    const timer = setTimeout(() => {
      setLetterClass("text-animate-hover");
    }, 3000);

    return () => clearTimeout(timer);
  }, []);

  const sendEmail = (e) => {
    e.preventDefault();
    setStatus("");

    emailjs
      .sendForm(
        "YOUR_SERVICE_ID", // e.g. 'service_abc123'
        "YOUR_TEMPLATE_ID", // e.g. 'template_xyz456'
        formRef.current,
        {
          publicKey: "YOUR_PUBLIC_KEY", // e.g. 'ABCD1234EFGH'
        }
      )
      .then(
        () => {
          setStatus("Message sent! I'll get back to you soon.");
          e.target.reset();
        },
        (error) => {
          console.error("EmailJS error:", error);
          setStatus("Something went wrong. Please try again later.");
        }
      );
  };

  return (
    <>
      <div
        id="contact"
        ref={ref}
        className={`container contact-page fade-section ${
          inView ? "in-view" : ""
        }`}
      >
        <div className="text-zone">
          <h1>
            <AnimatedLetters
              letterClass={letterClass}
              strArray={"Contact Me".split("")}
              index={15}
            />
          </h1>
          <p>
            Please use the form below to contact me, or email me directly at{" "}
            <span>chriszcodes@gmail.com</span>.
          </p>

          <div className="contact-form">
            <form ref={formRef} onSubmit={sendEmail}>
              <ul>
                <li className="half">
                  {/* matches {{name}} in EmailJS template */}
                  <input
                    type="text"
                    name="name"
                    placeholder="Name"
                    required
                  />
                </li>
                <li className="half">
                  {/* matches {{email}} in EmailJS template */}
                  <input
                    type="email"
                    name="email"
                    placeholder="Email"
                    required
                  />
                </li>
                <li>
                  {/* matches {{title}} in EmailJS template */}
                  <input
                    type="text"
                    name="title"
                    placeholder="Subject"
                    required
                  />
                </li>
                <li>
                  {/* matches {{message}} in EmailJS template */}
                  <textarea
                    name="message"
                    placeholder="Message"
                    required
                  />
                </li>
                <li>
                  <input
                    type="submit"
                    className="flat-button"
                    value="SEND"
                  />
                </li>
              </ul>
            </form>

            {status && <p className="status-message">{status}</p>}
          </div>
        </div>
      </div>

      <Loader type="pacman" />
    </>
  );
};

export default Contact;
